// NOVEL — not generated by CLI Printing Press.

package sqlguard

import "testing"

func TestValidateAllowsReads(t *testing.T) {
	for _, q := range []string{
		`SELECT 1`,
		`select id from resources`,
		`  SELECT id FROM resources;`,
		"-- a comment\nSELECT id FROM resources",
		`/* a comment */ SELECT id FROM resources`,
		`WITH days AS (SELECT id FROM resources) SELECT count(*) FROM days`,
		`SELECT json_extract(data,'$.totalSteps') FROM resources WHERE resource_type='steps'`,
		`SELECT ';' AS semicolon_in_a_literal`,
	} {
		if err := Validate(q); err != nil {
			t.Errorf("Validate(%q) = %v, want nil", q, err)
		}
	}
}

// TestValidateRefusesWrites covers the forms a prefix-only keyword check lets
// through. Each was a real bypass in a hand-written `sql` verb elsewhere in
// the library: a leading comment, a second statement, and a CTE-wrapped write.
func TestValidateRefusesWrites(t *testing.T) {
	for _, q := range []string{
		`DROP TABLE resources`,
		`INSERT INTO resources (id) VALUES ('x')`,
		`REPLACE INTO resources (id) VALUES ('x')`,
		`UPDATE resources SET data = '{}'`,
		`DELETE FROM resources`,
		`ATTACH DATABASE '/tmp/side.db' AS side`,
		`VACUUM INTO '/tmp/copy.db'`,
		`PRAGMA journal_mode=DELETE`,
		`SELECT 1; DROP TABLE resources`,
		"-- harmless\nDROP TABLE resources",
		`/* harmless */ DROP TABLE resources`,
		`; ATTACH DATABASE '/tmp/side.db' AS side`,
		``,
	} {
		if err := Validate(q); err == nil {
			t.Errorf("Validate(%q) = nil, want an error", q)
		}
	}
}

// TestValidateLetsCTEWrappedWritesThroughToTheHandle pins the one write shape
// this gate deliberately does not judge. "WITH x AS (...) INSERT ..." starts
// with an allowed keyword, and teaching the gate to parse CTE bodies would
// make it a SQL parser. The read-only handle answers SQLITE_READONLY instead —
// see TestGarminSQLBlastRadius/cte-insert, which runs this exact statement
// through the verb and asserts the archive's bytes are unchanged.
func TestValidateLetsCTEWrappedWritesThroughToTheHandle(t *testing.T) {
	const query = `WITH x AS (SELECT 1) INSERT INTO resources SELECT * FROM x`
	if err := Validate(query); err != nil {
		t.Fatalf("Validate(%q) = %v; the layering note in the package doc is now wrong", query, err)
	}
}

// TestValidateMessagesAreStable pins the two refusal sentences. Both the CLI
// verb and the MCP tool show them verbatim, so a caller that learns one has
// learned the other.
func TestValidateMessagesAreStable(t *testing.T) {
	for _, c := range []struct{ query, want string }{
		{`SELECT 1; DROP TABLE resources`, "only a single SELECT or WITH statement is allowed"},
		{`DROP TABLE resources`, "only SELECT queries are allowed"},
	} {
		err := Validate(c.query)
		if err == nil || err.Error() != c.want {
			t.Errorf("Validate(%q) = %v, want %q", c.query, err, c.want)
		}
	}
}

func TestStripLeadingSQLNoise(t *testing.T) {
	for _, c := range []struct{ in, want string }{
		{"  \n\tSELECT 1", "SELECT 1"},
		{";;SELECT 1", "SELECT 1"},
		{"-- x\nSELECT 1", "SELECT 1"},
		{"/* x */SELECT 1", "SELECT 1"},
		{"/* x */ -- y\n ; SELECT 1", "SELECT 1"},
		{"-- unterminated", ""},
		{"/* unterminated", ""},
	} {
		if got := StripLeadingSQLNoise(c.in); got != c.want {
			t.Errorf("StripLeadingSQLNoise(%q) = %q, want %q", c.in, got, c.want)
		}
	}
}

func TestHasTrailingSQLStatement(t *testing.T) {
	for _, c := range []struct {
		in   string
		want bool
	}{
		{`SELECT 1`, false},
		{`SELECT 1;`, false},
		{`SELECT 1;   `, false},
		{`SELECT 1; -- trailing comment`, false},
		{`SELECT 1; DROP TABLE resources`, true},
		{`SELECT ';' AS x`, false},
		{`SELECT "a;b" AS x`, false},
		{"SELECT `a;b` AS x", false},
		{`SELECT [a;b] AS x`, false},
	} {
		if got := HasTrailingSQLStatement(c.in); got != c.want {
			t.Errorf("HasTrailingSQLStatement(%q) = %v, want %v", c.in, got, c.want)
		}
	}
}
